import urllib.request
import re
import sys

SOURCES = [
    {
        "name": "Torah (Five Books of Moses)",
        "url": "https://www.gutenberg.org/cache/epub/8001/pg8001.txt",
    },
    {
        "name": "Bible (KJV)",
        "url": "https://www.gutenberg.org/cache/epub/10/pg10.txt",
    },
    {
        "name": "Quran",
        "url": "https://www.gutenberg.org/cache/epub/2800/pg2800.txt",
    },
]

OUTPUT_FILE = "abrahamic_corpus.txt"

GUTENBERG_HEADER = re.compile(
    r"\*\*\* START OF (THE|THIS) PROJECT GUTENBERG EBOOK .+? \*\*\*", re.IGNORECASE
)
GUTENBERG_FOOTER = re.compile(
    r"\*\*\* END OF (THE|THIS) PROJECT GUTENBERG EBOOK .+? \*\*\*", re.IGNORECASE
)


def strip_gutenberg_boilerplate(text: str) -> str:
    start_match = GUTENBERG_HEADER.search(text)
    end_match = GUTENBERG_FOOTER.search(text)
    if start_match:
        text = text[start_match.end():]
    if end_match:
        cut = text.find(GUTENBERG_FOOTER.pattern.split("\\*\\*\\*")[0])
        end_match2 = GUTENBERG_FOOTER.search(text)
        if end_match2:
            text = text[: end_match2.start()]
    return text.strip()


def fetch(url: str) -> str:
    print(f"  Fetching {url} ...", end=" ", flush=True)
    with urllib.request.urlopen(url, timeout=60) as resp:
        raw = resp.read()
    print("done")
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError:
        return raw.decode("latin-1")


def main():
    combined_parts = []

    for source in SOURCES:
        print(f"[{source['name']}]")
        text = fetch(source["url"])
        clean = strip_gutenberg_boilerplate(text)
        header = f"{'=' * 72}\n{source['name'].upper()}\n{'=' * 72}\n"
        combined_parts.append(header + clean)
        print(f"  Kept {len(clean):,} characters after stripping boilerplate.")

    corpus = "\n\n".join(combined_parts)

    with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
        f.write(corpus)

    print(f"\nWrote {len(corpus):,} characters to {OUTPUT_FILE}")


if __name__ == "__main__":
    main()

